// The status mark is pulse's one visual device: shape + word, never colour alone.
// Same markup for run status, the connection badge, and action feedback.
const LABELS = {
  passed: 'Passed', failed: 'Failed', running: 'Running', queued: 'Queued',
  checking: 'Checking API', connected: 'API connected', offline: 'API unreachable',
};

export function mark(state, label = LABELS[state]) {
  return `<span class="mark" data-state="${state}"><span class="mark-glyph" aria-hidden="true"></span>${label}</span>`;
}

// Connection state comes from a real health check (see main.js), not a constant.
export function renderBadge(state) {
  return `<span id="conn" role="status">${mark(state)}</span>`;
}

