:root {
  color-scheme: light dark;
  --bg: oklch(0.985 0.004 250);
  --surface: oklch(1 0 0);
  --ink: oklch(0.22 0.015 250);
  --muted: oklch(0.47 0.015 250);
  --line: oklch(0.91 0.006 250);
  --edge: oklch(0.6 0.012 250);      /* control borders, >=3:1 on surface */
  --accent: oklch(0.5 0.17 258);
  --on-accent: oklch(0.99 0 0);
  --ok: oklch(0.5 0.13 150);
  --bad: oklch(0.5 0.19 27);
  --bad-soft: oklch(0.97 0.02 27);
  --wait: oklch(0.5 0.1 70);
  --hover: oklch(0.96 0.006 250);
  --ring: var(--accent);
  --r-sm: 6px;
  --r-md: 10px;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: oklch(0.17 0.01 250);
    --surface: oklch(0.205 0.012 250);
    --ink: oklch(0.94 0.006 250);
    --muted: oklch(0.72 0.012 250);
    --line: oklch(0.29 0.012 250);
    --edge: oklch(0.52 0.014 250);
    --accent: oklch(0.72 0.13 258);
    --on-accent: oklch(0.17 0.02 258);
    --ok: oklch(0.76 0.14 150);
    --bad: oklch(0.72 0.16 25);
    --bad-soft: oklch(0.25 0.04 25);
    --wait: oklch(0.8 0.12 75);
    --hover: oklch(0.25 0.012 250);
  }
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 0.9375rem/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}
::selection { background: color-mix(in oklch, var(--accent) 25%, transparent); }
:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; border-radius: var(--r-sm); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.top, main { max-width: 72rem; margin-inline: auto; padding-inline: 1.5rem; }
.top {
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  padding-block: 1rem; border-bottom: 1px solid var(--line);
}
h1 { margin: 0; font-size: 1.0625rem; font-weight: 650; letter-spacing: -0.01em; }
h2 { margin: 0; font-size: 1.25rem; font-weight: 600; letter-spacing: -0.015em; }
main { padding-block: 2rem 3rem; }

.bar {
  display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between;
  gap: 1rem 2rem; margin-bottom: 1.25rem;
}
.hint { margin: 0.25rem 0 0; color: var(--muted); font-size: 0.875rem; }
.summary { margin: 0 0 0.5rem; color: var(--muted); font-size: 0.875rem; }
.summary strong { color: var(--bad); font-weight: 600; }

/* ---- the status mark: shape + word, one grammar everywhere ---- */
.mark {
  display: inline-flex; align-items: center; gap: 0.5em;
  font-size: 0.875rem; font-weight: 500; white-space: nowrap;
}
.mark-glyph {
  --c: var(--muted);
  width: 0.625rem; height: 0.625rem; flex: none;
  background: var(--c); border: 2px solid var(--c); border-radius: 50%;
}
[data-state="passed"] .mark-glyph, [data-state="connected"] .mark-glyph { --c: var(--ok); }
[data-state="failed"] .mark-glyph { --c: var(--bad); border-radius: 1px; transform: rotate(45deg) scale(0.85); }
[data-state="offline"] .mark-glyph { --c: var(--bad); background: none; border-radius: 1px; transform: rotate(45deg) scale(0.85); }
[data-state="queued"] .mark-glyph, [data-state="checking"] .mark-glyph,
[data-state="running"] .mark-glyph { --c: var(--wait); background: none; }
[data-state="failed"], [data-state="offline"] { color: var(--bad); }
[data-state="running"] .mark-glyph, [data-state="checking"] .mark-glyph { animation: beat 1.6s ease-out infinite; }
@keyframes beat { 50% { box-shadow: 0 0 0 4px color-mix(in oklch, var(--c) 25%, transparent); } }
@media (prefers-reduced-motion: reduce) {
  .mark-glyph { animation: none !important; }
}

#conn .mark {
  padding: 0.3rem 0.7rem; border: 1px solid var(--line); border-radius: 999px; background: var(--surface);
}

/* ---- table ---- */
.scroll {
  overflow-x: auto; background: var(--surface);
  border: 1px solid var(--line); border-radius: var(--r-md);
}
table { width: 100%; border-collapse: collapse; min-width: 40rem; }
th, td { padding: 0.625rem 1rem; text-align: start; border-bottom: 1px solid var(--line); height: 3.25rem; }
thead th {
  height: auto; padding-block: 0.5rem; color: var(--muted);
  font-size: 0.8125rem; font-weight: 500; background: var(--bg);
}
tbody tr:last-child > * { border-bottom: 0; }
tbody th { font-weight: 500; }
.id { font: 500 0.8125rem/1 ui-monospace, "SF Mono", Consolas, monospace; color: var(--muted); }
.num { text-align: end; font-variant-numeric: tabular-nums; }
.actions { width: 1%; white-space: nowrap; text-align: end; }
.actions .note { display: block; margin-top: 0.25rem; }
.actions .note:empty { display: none; }
tr[data-status="failed"] > * { background: var(--bad-soft); }
@media (hover: hover) { tbody tr:not([data-status="failed"]):hover > * { background: var(--hover); } }

/* ---- controls ---- */
.new-run { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem; }
.new-run label { color: var(--muted); font-size: 0.875rem; }
.new-run .note { flex-basis: 100%; text-align: end; }
.new-run .note:empty { display: none; }
select, .btn {
  height: 2.25rem; padding-inline: 0.875rem; font: inherit; font-size: 1rem; color: var(--ink);
  background: var(--surface); border: 1px solid var(--edge); border-radius: var(--r-sm);
}
.btn { font-size: 0.875rem; font-weight: 550; cursor: pointer; min-width: 5.5rem; touch-action: manipulation; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); }
@media (hover: hover) {
  .btn:hover { background: var(--hover); }
  .btn.primary:hover { background: color-mix(in oklch, var(--accent) 88%, black); }
}
.btn:active { transform: translateY(1px); }
.btn:disabled { cursor: progress; opacity: 0.75; }
.btn, select { transition: background-color 150ms ease-out; }

.empty {
  padding: 3rem 1.5rem; text-align: center; background: var(--surface);
  border: 1px dashed var(--edge); border-radius: var(--r-md);
}
.empty p { margin: 0.5rem 0 0; color: var(--muted); }

@media (max-width: 40rem) {
  .top, main { padding-inline: 1rem; }
  .new-run .note { text-align: start; }
}

