// ponytail: fixture rows until /api/runs exists; the header labels them "Sample data" so nobody trusts them.
const RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];
const SERVICES = [...new Set(RUNS.map((r) => r.service))].sort();

function row(r) {
  // Retry only where a run failed: one obvious action per screen, not four identical buttons.
  const action = r.status === 'failed'
    ? `<button type="button" class="btn" data-run="${r.id}">Retry</button>
       <span class="note" role="status"></span>`
    : '';
  return `<tr data-status="${r.status}">
    <th scope="row" class="id">${r.id}</th>
    <td>${r.service}</td>
    <td>${mark(r.status)}</td>
    <td class="num">${r.started}</td>
    <td class="num">${r.duration}</td>
    <td class="actions">${action}</td>
  </tr>`;
}

function table() {
  if (!RUNS.length) {
    return `<div class="empty">${mark('queued', 'No runs yet')}
      <p>Pick a service and start one with New run.</p></div>`;
  }
  const failed = RUNS.filter((r) => r.status === 'failed').length;
  return `<p class="summary">${RUNS.length} runs, ${failed ? `<strong>${failed} failed</strong>` : 'none failed'}</p>
    <div class="scroll"><table>
      <thead><tr>
        <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
        <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
        <th scope="col"><span class="sr-only">Actions</span></th>
      </tr></thead>
      <tbody>${RUNS.map(row).join('')}</tbody>
    </table></div>`;
}

// Runs an API call from a button and reports the real outcome next to it.
async function act(btn, note, busyLabel, call, okText) {
  // aria-disabled, not disabled: a disabled button drops keyboard focus to <body>.
  if (btn.getAttribute('aria-disabled') === 'true') return;
  const label = btn.textContent;
  btn.setAttribute('aria-disabled', 'true');
  btn.textContent = busyLabel;
  note.innerHTML = '';
  try {
    const res = await call();
    if (!res.ok) throw new Error(`the API answered ${res.status}`);
    note.innerHTML = mark('queued', okText);
  } catch (e) {
    const why = e instanceof TypeError ? 'the API is unreachable' : e.message;
    note.innerHTML = mark('failed', `Not sent: ${why}`);
  } finally {
    btn.disabled = false;
    btn.textContent = label;
  }
}

export function render() {
  document.querySelector('#app').innerHTML = `
    <header class="top">
      <h1>pulse</h1>
      ${renderBadge('checking')}
    </header>
    <main>
      <div class="bar">
        <div>
          <h2>Deploy runs</h2>
          <p class="hint">Sample data. Live runs appear once the runs API ships.</p>
        </div>
        <form id="new-run" class="new-run">
          <label for="service">Service</label>
          <select id="service" name="service">
            ${SERVICES.map((s) => `<option>${s}</option>`).join('')}
          </select>
          <button class="btn primary" type="submit">New run</button>
          <span class="note" role="status"></span>
        </form>
      </div>
      ${table()}
    </main>`;

  document.querySelectorAll('button[data-run]').forEach((b) => {
    b.addEventListener('click', () =>
      act(b, b.nextElementSibling, 'Retrying…', () => retryRun(b.dataset.run), 'Retry queued'));
  });

  const form = document.querySelector('#new-run');
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const service = form.service.value;
    act(form.querySelector('button'), form.querySelector('.note'), 'Starting…',
      () => createRun({ service }), `Run queued for ${service}`);
  });

  health()
    .then(() => 'connected', () => 'offline')
    .then((s) => { document.querySelector('#conn').innerHTML = mark(s); });
}

render();

