const { chromium } = require('C:/Users/Ikran/AppData/Local/Temp/pulse-pw/node_modules/playwright');
const URL = 'http://localhost:5287/';
const OUT = 'C:/Users/Ikran/AppData/Local/Temp/pulse-shots/';
(async () => {
  require('fs').mkdirSync(OUT, { recursive: true });
  const b = await chromium.launch();
  const report = {};
  for (const scheme of ['light', 'dark']) {
    for (const w of [320, 768, 1280, 1920]) {
      const p = await b.newPage({ viewport: { width: w, height: 800 }, colorScheme: scheme, reducedMotion: 'reduce' });
      const logs = [];
      p.on('console', (m) => logs.push(m.type() + ': ' + m.text()));
      p.on('pageerror', (e) => logs.push('pageerror: ' + e.message));
      await p.goto(URL); await p.waitForTimeout(600);
      const overflow = await p.evaluate(() => [...document.querySelectorAll('*')]
        .filter((el) => el.scrollWidth > el.clientWidth + 1 && getComputedStyle(el).overflowX === 'visible')
        .map((el) => el.tagName + '.' + el.className));
      const small = await p.evaluate(() => [...document.querySelectorAll('button,select,a[href]')]
        .map((el) => [el, el.getBoundingClientRect()]).filter(([, r]) => r.width && (r.width < 24 || r.height < 24))
        .map(([el, r]) => el.tagName + ' ' + r.width + 'x' + r.height));
      report[scheme + w] = { overflow, small, docW: await p.evaluate(() => document.documentElement.scrollWidth), logs };
      await p.screenshot({ path: `${OUT}${scheme}-${w}.png`, fullPage: true });
      if (w === 1280) {
        await p.click('button[data-run]'); await p.waitForTimeout(600);
        await p.click('#new-run button'); await p.waitForTimeout(600);
        await p.keyboard.press('Tab'); await p.keyboard.press('Tab');
        report[scheme + 'focus'] = await p.evaluate(() => document.activeElement.outerHTML.slice(0, 80));
        report[scheme + 'notes'] = await p.evaluate(() => [...document.querySelectorAll('.note, #conn')].map((n) => n.textContent.trim()));
        await p.screenshot({ path: `${OUT}${scheme}-actions.png` });
      }
      await p.close();
    }
  }
  // zoom 200%: a 640px-wide viewport at 2x text equivalent
  const z = await b.newPage({ viewport: { width: 640, height: 800 }, deviceScaleFactor: 2 });
  await z.goto(URL); await z.evaluate(() => { document.documentElement.style.fontSize = '200%'; });
  report.zoomDocW = await z.evaluate(() => document.documentElement.scrollWidth);
  await z.screenshot({ path: OUT + 'zoom200.png', fullPage: true });
  console.log(JSON.stringify(report, null, 1));
  await b.close();
})();

const { chromium } = require('C:/Users/Ikran/AppData/Local/Temp/pulse-pw/node_modules/playwright');
const URL = 'http://localhost:5287/';
const OUT = 'C:/Users/Ikran/AppData/Local/Temp/pulse-shots/';
(async () => {
  require('fs').mkdirSync(OUT, { recursive: true });
  const b = await chromium.launch();
  const report = {};
  for (const scheme of ['light', 'dark']) {
    for (const w of [320, 768, 1280, 1920]) {
      const p = await b.newPage({ viewport: { width: w, height: 800 }, colorScheme: scheme, reducedMotion: 'reduce' });
      const logs = [];
      p.on('console', (m) => logs.push(m.type() + ': ' + m.text()));
      p.on('pageerror', (e) => logs.push('pageerror: ' + e.message));
      await p.goto(URL); await p.waitForTimeout(600);
      const overflow = await p.evaluate(() => [...document.querySelectorAll('*')]
        .filter((el) => el.scrollWidth > el.clientWidth + 1 && getComputedStyle(el).overflowX === 'visible')
        .map((el) => el.tagName + '.' + el.className));
      const small = await p.evaluate(() => [...document.querySelectorAll('button,select,a[href]')]
        .map((el) => [el, el.getBoundingClientRect()]).filter(([, r]) => r.width && (r.width < 24 || r.height < 24))
        .map(([el, r]) => el.tagName + ' ' + r.width + 'x' + r.height));
      report[scheme + w] = { overflow, small, docW: await p.evaluate(() => document.documentElement.scrollWidth), logs };
      await p.screenshot({ path: `${OUT}${scheme}-${w}.png`, fullPage: true });
      if (w === 1280) {
        const order = [];
        for (let i = 0; i < 4; i++) { await p.keyboard.press('Tab'); order.push(await p.evaluate(() => document.activeElement.id || document.activeElement.textContent.trim())); }
        report[scheme + 'taborder'] = order;
        await p.keyboard.press('Enter'); await p.waitForTimeout(600);
        report[scheme + 'focusAfterRetry'] = await p.evaluate(() => document.activeElement.textContent.trim());
        await p.click('#new-run button'); await p.waitForTimeout(600);
        report[scheme + 'notes'] = await p.evaluate(() => [...document.querySelectorAll('.note, #conn')].map((n) => n.textContent.trim()));
        await p.screenshot({ path: `${OUT}${scheme}-actions.png` });
      }
      await p.close();
    }
  }
  // zoom 200%: a 640px-wide viewport at 2x text equivalent
  const z = await b.newPage({ viewport: { width: 640, height: 800 }, deviceScaleFactor: 2 });
  await z.goto(URL); await z.evaluate(() => { document.documentElement.style.fontSize = '200%'; });
  report.zoomDocW = await z.evaluate(() => document.documentElement.scrollWidth);
  await z.screenshot({ path: OUT + 'zoom200.png', fullPage: true });
  console.log(JSON.stringify(report, null, 1));
  await b.close();
})();
